css:
:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
  --text-muted: #a1a1aa;
  --accent: #0ea5e9;
  --success: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;

  /* Uma cor por fonte de receita — a mesma em pílula, gráfico e avatar. */
  --src-empresa: #0ea5e9;
  --src-impressionart: #8b5cf6;
  --src-moto: #f59e0b;
  --src-mos: #22c55e;
  --src-nata: #ec4899;

  --fonte: 'Manrope', sans-serif;
  --fonte-titulo: 'Sora', sans-serif;
  --fonte-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-base); color: var(--text); font-family: var(--fonte); }

/* Número em tabela, card ou badge nunca "dança" ao atualizar. */
.bs-num { font-variant-numeric: tabular-nums; }

.bs-sheet-camada {
  position: fixed; inset: 0; z-index: 50;
  display: flex; align-items: flex-end;
}
/* O fundo é irmão do painel, não pai: clique no conteúdo não sobe pra ele. */
.bs-sheet-fundo { position: absolute; inset: 0; background: rgba(0, 0, 0, 0.6); }

.bs-sheet {
  position: relative; z-index: 10;
  width: 100%; max-height: 90vh; overflow-y: auto; overscroll-behavior: contain;
  padding: 12px 20px 32px;
  border-top: 1px solid var(--border); border-radius: 24px 24px 0 0;
  background: var(--bg-surface);
}
.bs-sheet::-webkit-scrollbar { display: none; }

/* Não arrasta nada: é a affordance de "isto veio de baixo", e por isso some
   no desktop, onde o painel não vem de lugar nenhum. */
.bs-sheet-puxador {
  width: 36px; height: 4px; margin: 0 auto 16px;
  border-radius: 999px; background: var(--border);
}

@media (min-width: 768px) {
  .bs-sheet-camada { align-items: center; justify-content: center; }
  .bs-sheet {
    width: 420px; padding: 12px 20px 24px;
    border: 1px solid var(--border); border-radius: 24px;
  }
  .bs-sheet-puxador { display: none; }
}

.bs-sheet-topo { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; }
.bs-sheet-titulo { font-family: var(--fonte-titulo); font-size: 18px; font-weight: 600; color: var(--text); }
.bs-sheet-fechar {
  display: grid; place-items: center; width: 32px; height: 32px;
  border: none; border-radius: 8px; color: var(--text-muted); background: var(--bg-card);
}
.bs-sheet-ic { width: 16px; height: 16px; }

.bs-campo { margin-bottom: 16px; }
.bs-campo-duplo { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }

.bs-rotulo {
  display: block; margin-bottom: 6px;
  font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted);
}

.bs-input {
  width: 100%; padding: 10px 12px;
  border: 1px solid var(--border); border-radius: 8px;
  font-family: var(--fonte); font-size: 13px; color: var(--text);
  background: var(--bg-base); outline: none;
  /* Sem isto o select volta a ser o widget do sistema, claro e fora do tema. */
  appearance: none;
}
.bs-input:focus { border-color: var(--accent); }

/* O erro do salvamento fica acima das ações, e some quando não há erro — o
   botão nunca muda de lugar por causa dele. */
.bs-sheet-erro { margin-bottom: 16px; font-size: 12px; color: var(--danger); }
.bs-sheet-erro[hidden] { display: none; }

.bs-sheet-acoes { display: flex; gap: 8px; margin-top: 20px; }

/* Existe, mas não disputa: sem texto e sem crescer na linha. */
.bs-excluir {
  display: grid; place-items: center; padding: 14px 16px; border-radius: 12px;
  color: var(--danger);
  border: 1px solid color-mix(in srgb, var(--danger) 40%, transparent);
  background: color-mix(in srgb, var(--danger) 10%, transparent);
}

.bs-salvar {
  flex: 1; padding: 14px; border: none; border-radius: 12px;
  font-family: var(--fonte-titulo); font-size: 15px; font-weight: 600;
  color: var(--bg-base); background: var(--accent);
}
.bs-salvar:disabled, .bs-excluir:disabled { opacity: 0.5; }
